// WithSessionStateLocks acquires the per-session state lock in each git common
// dir, then runs fn. Lock paths are deduplicated and sorted so callers that
// span repositories or worktrees can safely acquire more than one lock.
func WithSessionStateLocks(ctx context.Context, sessionID string, commonDirs []string, fn func() error) error {
	locks := make([]stateLock, 0, len(commonDirs))
	seen := make(map[string]struct{}, len(commonDirs))
	for _, commonDir := range commonDirs {
		lock, err := stateLockInCommonDir(commonDir, sessionID)
		if err != nil {
			return err
		}
		if _, ok := seen[lock.path]; ok {
			continue
		}
		seen[lock.path] = struct{}{}
		locks = append(locks, lock)
	}
	// Sorted by absolute path so callers spanning repositories acquire in a
	// consistent order and cannot deadlock against each other.
	slices.SortFunc(locks, func(a, b stateLock) int { return strings.Compare(a.path, b.path) })

	releases := make([]func(), 0, len(locks))
	releaseAll := func() {
		for i := len(releases) - 1; i >= 0; i-- {
			releases[i]()
		}
	}
	for _, lock := range locks {
		if err := ctx.Err(); err != nil {
			releaseAll()
			return fmt.Errorf("session state lock canceled: %w", err)
		}
		release, err := flock.AcquireIn(lock.root, lock.name)
		if err != nil {
			releaseAll()
			return fmt.Errorf("acquire session state lock: %w", err)
		}
		releases = append(releases, release)
	}
	defer releaseAll()

	return fn()
}

// ErrMutationSkip signals MutateSessionState to skip the save without
// treating fn's return as an error. Use it when the mutation function
// observes the loaded state and decides no write is needed (for example,
// when a merge produces no new entries).
var ErrMutationSkip = errors.New("session state mutation skipped")

// ErrStateNotFound is returned by MutateSessionState when no state file
// exists for the session ID (typically because the event arrived before
// InitializeSession ran). Callers that need to distinguish "no state"
// from a successful no-op can branch on errors.Is(err, ErrStateNotFound).
var ErrStateNotFound = errors.New("session state not found")

// RecordFilesTouched merges paths into the session's FilesTouched, used by
// mid-turn lifecycle events (per-tool-use hooks) so PostCommit's carry-forward
// decision sees an accurate file list. Caller must pre-normalize paths to
// repo-relative form. No-ops when the session state doesn't exist or the
// merge produced no changes.
func RecordFilesTouched(ctx context.Context, sessionID string, modified, added, deleted []string) error {
	if len(modified) == 0 && len(added) == 0 && len(deleted) == 0 {
		return nil
	}
	err := MutateSessionState(ctx, sessionID, func(state *SessionState) error {
		before := slices.Clone(state.FilesTouched)
		hashesBefore := len(state.TouchedFileHashes)
		MergeUnhashedFilesTouched(state, modified, added, deleted)
		if slices.Equal(before, state.FilesTouched) && hashesBefore == len(state.TouchedFileHashes) {
			return ErrMutationSkip
		}
		return nil
	})
	if errors.Is(err, ErrStateNotFound) {
		return nil
	}
	return err
}

// stateLock names a per-session lock file two ways: path, for dedup and for the
// deterministic ordering WithSessionStateLocks needs across repositories, and
// (root, name) for the acquire itself so the session-ID-derived name resolves
// inside the git common dir rather than as an assembled string.
type stateLock struct {
// Package entiredir owns access to the repository's .entire directory.
//
// Every non-test read and write under .entire goes through the single *os.Root
// this package hands out, rather than through an absolute path assembled by the
// caller. Two properties follow from that, and neither survives if a call site
// reverts to os.ReadFile/os.WriteFile on a joined path:
//
//   - Containment. .entire holds paths named from agent-supplied session IDs,
//     tool-use IDs, and tree paths. A root confines every open to the directory
//     at the kernel level, so a crafted name cannot escape it, and a symlink
//     swapped in between resolution and open (TOCTOU) surfaces as an error
//     rather than a redirected write.
//   - One directory handle per worktree. The root is opened once and memoized,
//     so the hot hook paths stop paying an OpenRoot per state file, and every
//     consumer observes the same directory even if .entire is renamed or
//     replaced underneath a long-running process.
//
// Creation is deliberately lazy and split across two entry points. Open creates
// .entire because its callers are about to write; OpenForRead never creates,
// because a command that only looks must leave an untouched repo untouched.
// That distinction is load-bearing for logging in particular: the log file is
// created by the first line actually written, so a command that logs nothing
// (completion, version, help) must not leave an .entire behind.
//
// Reset exists for the paths that delete the directory (entire disable,
// entire clean) and for tests. A cached root that outlives its directory is a
// handle to an unlinked inode: writes through it succeed and land nowhere.
package entiredir

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// dirPerm is the mode .entire is created with. It matches the mode the
// directory already had when each consumer created its own subdirectory.
const dirPerm = 0o750

// ReadFile reads an Entire-owned file without following a symlink at the leaf.
func ReadFile(root *os.Root, name string) ([]byte, error) {
	return osroot.ReadFileNoFollow(root, name) //nolint:wrapcheck // preserve os error classification
}

// WriteFile atomically replaces an Entire-owned file. Renaming a newly-created
// temporary file over name replaces a planted leaf symlink rather than opening
// and truncating its target.
func WriteFile(root *os.Root, name string, data []byte, perm os.FileMode) error {
	return jsonutil.WriteFileAtomicIn(root, name, data, perm) //nolint:wrapcheck // caller supplies path context
}

// Open returns the shared *os.Root for the current worktree's .entire
// directory, creating the directory if it does not exist. Use it from write
// paths; read-only callers want OpenForRead.
//
// The returned root is owned by this package and shared with every other
// caller. Do not close it.
func Open(ctx context.Context) (*os.Root, error) {
	worktreeRoot, err := anchor(ctx)
	if err != nil {
		return nil, err
	}
	return OpenAt(worktreeRoot)
}

// OpenForRead is Open without creating .entire. A missing directory is
// reported as fs.ErrNotExist, which callers classify with errors.Is.
func OpenForRead(ctx context.Context) (*os.Root, error) {
	worktreeRoot, err := anchor(ctx)
	if err != nil {
		return nil, err
	}
	return OpenAtForRead(worktreeRoot)
}

// OpenAt is Open for an explicit worktree root, for the callers that already
// resolved one (or that act on a worktree other than the current directory).
func OpenAt(worktreeRoot string) (*os.Root, error) {
	return open(worktreeRoot, true)
}

// OpenAtForRead is OpenForRead for an explicit worktree root.
func OpenAtForRead(worktreeRoot string) (*os.Root, error) {
	return open(worktreeRoot, false)
}

// OpenerAt returns a thunk that calls OpenAt when invoked.
func OpenerAt(worktreeRoot string) func() (*os.Root, error) {
	return func() (*os.Root, error) { return OpenAt(worktreeRoot) }
}

// Path returns the absolute path of the current worktree's .entire directory.
// It is for messages and for the few consumers that must hand a path to an
// external process; it is not an invitation to do I/O on the result.
func Path(ctx context.Context) (string, error) {
	worktreeRoot, err := anchor(ctx)
	if err != nil {
		return "", err
	}
	return filepath.Join(worktreeRoot, paths.EntireDir), nil
}

// Reset closes and forgets every cached root. Call it after deleting .entire:
// a root cached across the deletion refers to an unlinked directory, so writes
// through it succeed and land nowhere.
//
// The registry is shared with the other anchors, so this clears them too. That
// is the behaviour teardown wants — a repo whose .entire just went away is not a
// repo whose .git root is worth keeping — and tests get one reset to call.
func Reset() {
	osroot.ResetShared()
}

// Name converts a repo-relative path under .entire (for example
// paths.EntireTmpDir) to a name relative to the .entire root. The repo-relative
// constants stay as they are because git paths, settings display, and gitignore
// entries all need them; this is the one-line bridge to root-relative I/O.
//
// A path outside .entire is an error rather than a silent passthrough: the
// alternative is a name that resolves inside .entire but means something else.
func Name(repoRelPath string) (string, error) {
	cleaned := filepath.ToSlash(filepath.Clean(filepath.FromSlash(repoRelPath)))
	if cleaned == paths.EntireDir {
		return ".", nil
	}
	rest, ok := strings.CutPrefix(cleaned, paths.EntireDir+"/")
	if !ok || rest == "" {
		return "", fmt.Errorf("%q is not under %s", repoRelPath, paths.EntireDir)
	}
	return rest, nil
}

// MustName is Name for package-level constants that are known to be under
// .entire. It panics on a path that is not, which can only be a programming
// error in a literal.
func MustName(repoRelPath string) string {
	name, err := Name(repoRelPath)
	if err != nil {
		panic(err)
	}
	return name
}

// anchor resolves the directory .entire sits in: the git worktree root, falling
// back to the current directory only on git's positive "not a repository"
// verdict.
//
// The fallback is load-bearing — `entire enable` runs in a directory that is not
// a repository yet — and gating it on paths.ErrNotARepository is what keeps it
// narrow. That sentinel means git ran and said there is no repository here.
// Every other failure (git off $PATH, a cancelled context, dubious ownership, a
// permission error, malformed output) means "we could not find out", and
// answering that with the current directory is how the paths.AbsPath fallback
	if content == "" {
		return nil
	}
	parts := strings.Split(content, "\n\n---\n\n")
	var result []string
	for _, p := range parts {
		trimmed := strings.TrimSpace(p)
		if trimmed != "" {
			result = append(result, trimmed)
		}
	}
	return result
}

// readPromptsFromFilesystem reads prompt.txt from the filesystem session metadata directory.
// This file is written at turn start and backfilled at turn end, providing prompt data
// even for mid-turn commits.
func readPromptsFromFilesystem(ctx context.Context, state *SessionState) []string {
	root := storedSessionRootOrNil(ctx, state)
	if root == nil {
		return nil
	}
	return readPromptsIn(root, state.SessionID)
}

// readPromptsIn is readPromptsFromFilesystem against an already-opened .entire
// root (storedSessionRoot for a condensation).
func readPromptsIn(root *os.Root, sessionID string) []string {
	name, err := storedSessionFileName(sessionID, paths.PromptFileName)
	if err != nil {
		return nil
	}
	data, err := entiredir.ReadFile(root, name)
	if err != nil || len(data) == 0 {
		return nil
	}
	return splitPromptContent(string(data))
}

// storedTranscriptFileNames are the names the turn-end transcript copy may
// have under .entire/metadata/<session>/, current spelling first: every staged
// file except the prompt.
var storedTranscriptFileNames = stagedSessionFiles[1:]

// resolveStoredTranscript finds the session's stored turn-end transcript: the
// sanitized copy every Stop writes to .entire/metadata/<session>/full.jsonl
// (see lifecycle.go), or the legacy full.log. ok is false when no regular file
// exists under either name, which is normal before the first Stop and after
// condensation released it.
func resolveStoredTranscript(ctx context.Context, state *SessionState) (root *os.Root, name string, info fs.FileInfo, ok bool) {
	root = storedSessionRootOrNil(ctx, state)
	if root == nil {
		return nil, "", nil, false
	}
	name, info, ok = resolveStoredTranscriptIn(root, state.SessionID)
	if !ok {
		return nil, "", nil, false
	}
	return root, name, info, true
}

// resolveStoredTranscriptIn is resolveStoredTranscript against an
// already-opened .entire root. Every component is Lstat'ed without following a
// symlink, so a symlinked metadata directory or transcript is not found.
func resolveStoredTranscriptIn(root *os.Root, sessionID string) (name string, info fs.FileInfo, ok bool) {
	for _, base := range storedTranscriptFileNames {
		candidate, err := storedSessionFileName(sessionID, base)
		if err != nil {
			return "", nil, false
		}
		stat, statErr := osroot.LstatNoSymlinks(root, candidate)
		if statErr == nil && stat.Mode().IsRegular() {
			return candidate, stat, true
		}
	}
	return "", nil, false
}

// storedTranscriptSize returns the size of the session's stored turn-end
// transcript (see resolveStoredTranscript).
//
// The size is in the coordinate CheckpointTranscriptSize is measured in —
// sanitized, not image-externalized (CondenseResult.TranscriptSizeBaseline) —
// which is what makes the growth comparison in sessionHasNewContent sound.
func storedTranscriptSize(ctx context.Context, state *SessionState) (size int64, ok bool) {
	_, _, info, ok := resolveStoredTranscript(ctx, state)
	if !ok {
		return 0, false
	}
	return info.Size(), true
}

// readStoredTranscript returns the session's stored turn-end transcript (see
// resolveStoredTranscript), or nil when there is none or it is empty.
func readStoredTranscript(ctx context.Context, state *SessionState) []byte {
	root := storedSessionRootOrNil(ctx, state)
	if root == nil {
		return nil
	}
	return readStoredTranscriptIn(root, state.SessionID)
}

package strategy

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/entiredir"
	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/testutil"
)

// A session's turns can end in a worktree other than its home (the agent was
// resumed there). These tests home a session in the main worktree, then run
// its hooks from a linked one. They use t.Chdir — do NOT add t.Parallel().

// homedSession starts sessionID in mainDir with one turn-end step that
// creates the untracked file home.go, and returns the linked worktree.
func homedSession(t *testing.T, sessionID string) (s *ManualCommitStrategy, mainDir, linkedDir string) {
	t.Helper()
	mainDir = setupGitRepo(t)
	linkedDir = filepath.Join(t.TempDir(), "linked")
	testutil.RunGit(t, mainDir, "worktree", "add", linkedDir, "-b", "linked-branch")
	testutil.WriteFile(t, linkedDir, "linked-only.txt", "advance the linked branch")
	testutil.GitAdd(t, linkedDir, "linked-only.txt")
	testutil.RunGit(t, linkedDir, "commit", "-q", "-m", "linked commit")

	s = &ManualCommitStrategy{}
	chdirWorktree(t, mainDir)
	testutil.WriteFile(t, mainDir, "home.go", "package home // written at home")
	saveStepIn(t, s, sessionID, []string{"home.go"}, nil)
	return s, mainDir, linkedDir
}

func chdirWorktree(t *testing.T, dir string) {
	t.Helper()
	t.Chdir(dir)
	paths.ClearWorktreeRootCache()
}

func saveStepIn(t *testing.T, s *ManualCommitStrategy, sessionID string, newFiles, modified []string) {
	t.Helper()
	require.NoError(t, s.SaveStep(t.Context(), StepContext{
		SessionID:     sessionID,
		NewFiles:      newFiles,
		ModifiedFiles: modified,
		MetadataDir:   paths.SessionMetadataDirFromSessionID(sessionID),
		CommitMessage: "Checkpoint",
		AuthorName:    "Test",
		AuthorEmail:   "test@test.com",
		AgentType:     agent.AgentTypeClaudeCode,
	}))
}

func mustLoad(t *testing.T, s *ManualCommitStrategy, sessionID string) *SessionState {
	t.Helper()
	state, err := s.loadSessionState(t.Context(), sessionID)
	require.NoError(t, err)
	require.NotNil(t, state)
	return state
}

// Case 1: a turn ending in the linked worktree records its own file against
// that worktree, never as the home's: the home's untracked file isn't read as
// deleted (it isn't in that tree), and the home's base doesn't move.
func TestGuestTurnEnd_RecordsAgainstItsOwnWorktree(t *testing.T) {
	s, mainDir, linkedDir := homedSession(t, "guest-turn-end")
	before := mustLoad(t, s, "guest-turn-end")
	require.NotEqual(t, touchedFileDeleted, before.TouchedFileHashes["home.go"])

	chdirWorktree(t, linkedDir)
	// A turn with no visible changes, then one that writes a file of its own.
	require.NoError(t, s.RecordVanishedUntrackedFiles(t.Context(), "guest-turn-end"))
	testutil.WriteFile(t, linkedDir, "guest.go", "package guest")
	saveStepIn(t, s, "guest-turn-end", []string{"guest.go"}, nil)

	after := mustLoad(t, s, "guest-turn-end")
	assert.Equal(t, before.TouchedFileHashes["home.go"], after.TouchedFileHashes["home.go"], "the home's untracked file was recorded as deleted from another tree")
	assert.Equal(t, []string{"home.go"}, after.FilesTouched, "the home's record should hold only the home's files")
	assert.Equal(t, before.BaseCommit, after.BaseCommit, "the base moved to another tree's HEAD")
	assert.True(t, isSessionHomeWorktree(mustEvalSymlinks(t, mainDir), after), "the session left its home: %s", after.WorktreePath)

	linked := after.OtherWorktrees[linkedKey(t, linkedDir)]
	require.NotNil(t, linked, "the linked worktree's file wasn't recorded for it")
	assert.Equal(t, []string{"guest.go"}, linked.FilesTouched)
	assert.NotEmpty(t, linked.TouchedFileHashes["guest.go"])
	assert.Equal(t, testutil.GetHeadHash(t, linkedDir), linked.BaseCommit)
}

// The same path edited at home and in the linked worktree is two records,
// each with its own tree's content.
func TestGuestTurnEnd_SamePathIsRecordedPerWorktree(t *testing.T) {
	s, _, linkedDir := homedSession(t, "guest-same-path")
	homeHash := mustLoad(t, s, "guest-same-path").TouchedFileHashes["home.go"]
	require.NotEmpty(t, homeHash)

	chdirWorktree(t, linkedDir)
	testutil.WriteFile(t, linkedDir, "home.go", "package home // the linked tree's version")
	saveStepIn(t, s, "guest-same-path", []string{"home.go"}, nil)

	state := mustLoad(t, s, "guest-same-path")
	assert.Equal(t, homeHash, state.TouchedFileHashes["home.go"], "the home's hash was overwritten by another tree's content")
	linked := state.OtherWorktrees[linkedKey(t, linkedDir)]
	require.NotNil(t, linked)
	assert.NotEmpty(t, linked.TouchedFileHashes["home.go"])
	assert.NotEqual(t, homeHash, linked.TouchedFileHashes["home.go"])
}

